-- Update PDF files with searchable content
UPDATE pdf_files SET content = 
  'ASTRA è l''Associazione Studenti Bocconi. ASTRA si occupa di rappresentanza studentesca, eventi sociali, servizi per studenti, borse di studio, agevolazioni, tasse universitarie, vita studentesca, attività culturali, networking, supporto accademico, orientamento, guida per studenti, informazioni su corsi, esami, procedure burocratiche, erasmus, exchange, stage, tirocini, career service, placement, recruiting, job placement, lavoro. ASTRA organizza eventi come aperitivi, feste, conference, seminari, workshop, networking events, career fairs. ASTRA offre servizi come dispense, appunti, guide, calcolatori per media e voti, pianificazione studi, study planner, GPA calculator, graduation calculator. ASTRA rappresenta gli studenti nei consigli di facoltà e nelle commissioni universitarie. ASTRA è il punto di riferimento per la vita studentesca alla Bocconi. ASTRA aiuta con tasse universitarie, borse di studio ISU, agevolazioni economiche, ISEE, riduzioni tasse, esoneri, scholarship, financial aid. ASTRA fornisce informazioni su alloggi, residenze, housing, trasporti, mensa, servizi campus.'
WHERE name = 'astra description';

UPDATE pdf_files SET content = 
  'Bintouch FAQ - Domande frequenti su Bintouch, piattaforma digitale per studenti Bocconi. Bintouch è la piattaforma e-learning utilizzata per corsi, lezioni online, materiali didattici, comunicazioni con professori, assignment, homework, progetti di gruppo, discussioni, forum studenti. Include informazioni dettagliate su come usare Bintouch, risoluzione problemi tecnici, accesso alla piattaforma, login, password, reset password, sync, mobile app, notifiche push, submission deadlines, consegne, grading, feedback, collaborazione tra studenti, sharing files, video lectures, live sessions, recording, attendance tracking, participation, quiz, esami online, virtual classroom, breakout rooms, chat, messaging, calendar, schedule, syllabus, grades, transcript, course materials, reading list, biblioteca digitale.'
WHERE name LIKE '%bintouch%';